const item = $input.first().json;
const body = item.body || item;
const headers = item.headers || {};
const headerSecret = headers['x-n8n-deploy-secret'] || headers['X-N8N-Deploy-Secret'];
if (!$env.DEPLOY_WEBHOOK_SECRET) {
  throw new Error('DEPLOY_WEBHOOK_SECRET is required');
}
if (headerSecret !== $env.DEPLOY_WEBHOOK_SECRET) {
  throw new Error('Invalid deploy webhook secret');
}
const repo = body.repository?.full_name || $env.DEPLOY_REPO || 'OWNER/REPO';
if (!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repo)) {
  throw new Error(`Refusing unsafe repo: ${repo}`);
}
const ref = body.ref || $env.DEPLOY_BRANCH || 'refs/heads/main';
const branch = ref.replace('refs/heads/', '');
if (branch.includes('..') || !/^[A-Za-z0-9._/-]+$/.test(branch)) {
  throw new Error(`Refusing unsafe branch: ${branch}`);
}
const workflowPath = body.workflow_path || body.workflowPath || $env.DEPLOY_WORKFLOW_PATH || 'staging/personal-productivity-safe.json';
if (!workflowPath.startsWith('staging/') || workflowPath.includes('..') || !/^[A-Za-z0-9._/-]+$/.test(workflowPath)) {
  throw new Error(`Refusing unsafe workflow path: ${workflowPath}`);
}
const fileName = workflowPath.split('/').pop();
const stagingInput = `/files/git/${workflowPath}`;
const productionInput = `/files/git/production/${fileName}`;
const downloadUrl = `https://raw.githubusercontent.com/${repo}/${branch}/${workflowPath}`;
const displayName = fileName.replace(/\.json$/, '').replace(/[-_]/g, ' ');
const publishStaging = String($env.DEPLOY_PUBLISH_STAGING || '').toLowerCase() === 'true';
const downloadJson = `const fs=require('fs');const [url,out]=process.argv.slice(1);const headers={};if(process.env.GITHUB_TOKEN)headers.Authorization='Bearer '+process.env.GITHUB_TOKEN;fetch(url,{headers}).then(async r=>{if(!r.ok)throw new Error('Download failed '+r.status+' '+r.statusText);fs.writeFileSync(out,await r.text());}).catch(e=>{console.error(e.message);process.exit(1);});`;
const hardenJson = `const fs=require('fs');const p=process.argv[1];const n=process.argv[2];const j=JSON.parse(fs.readFileSync(p,'utf8'));j.active=false;j.name=(j.name||n)+' - Staging Candidate';fs.writeFileSync(p,JSON.stringify(j,null,2));`;
const readIdJson = `const fs=require('fs');const j=JSON.parse(fs.readFileSync(process.argv[1],'utf8'));process.stdout.write(j.id||'');`;
const writeApprovalJson = `const fs=require('fs');const path=require('path');const [out,b64]=process.argv.slice(1);fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,Buffer.from(b64,'base64').toString('utf8'));`;
const promptFiles = ['supervisor.md', 'inbox-agent.md', 'calendar-agent.md'];
const baseUrl = ($env.PUBLIC_N8N_BASE_URL || '').replace(/\/$/, '');
if (!baseUrl) {
  throw new Error('PUBLIC_N8N_BASE_URL is required to build the approval backoffice link');
}
function randomHex(bytes) {
  const alphabet = '0123456789abcdef';
  const values = new Uint8Array(bytes);
  if (globalThis.crypto?.getRandomValues) {
    globalThis.crypto.getRandomValues(values);
  } else {
    for (let i = 0; i < values.length; i += 1) {
      values[i] = Math.floor(Math.random() * 256);
    }
  }
  return Array.from(values, (value) => alphabet[(value >> 4) & 15] + alphabet[value & 15]).join('');
}
const approvalId = randomHex(12);
const approvalRecordPath = `/files/approvals/deploy-${approvalId}.json`;
const approvalRecord = {
  id: approvalId,
  type: 'production-promotion',
  repo,
  branch,
  workflowPath,
  fileName,
  stagingInput,
  productionInput,
  createdAt: new Date().toISOString(),
  expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
};
const approvalRecordB64 = Buffer.from(JSON.stringify(approvalRecord, null, 2), 'utf8').toString('base64');
const importCommandParts = [
  `mkdir -p '/files/git/staging'`,
  `mkdir -p '/files/git/prompts'`,
  `mkdir -p '/files/approvals'`,
  ...promptFiles.map((promptFile) => `node -e "${downloadJson}" 'https://raw.githubusercontent.com/${repo}/${branch}/prompts/${promptFile}' '/files/git/prompts/${promptFile}'`),
  `node -e "${downloadJson}" '${downloadUrl}' '${stagingInput}'`,
  `node -e "${hardenJson}" '${stagingInput}' '${displayName}'`,
  `node -e "${writeApprovalJson}" '${approvalRecordPath}' '${approvalRecordB64}'`,
  `n8n import:workflow --input='${stagingInput}'`
];
if (publishStaging) {
  importCommandParts.push(`WORKFLOW_ID=$(node -e "${readIdJson}" '${stagingInput}') && test -n "$WORKFLOW_ID" && n8n publish:workflow --id="$WORKFLOW_ID"`);
}
const importCommand = importCommandParts.join(' && ');
const approvalUrl = `${baseUrl}/webhook/deploy-approval?id=${encodeURIComponent(approvalId)}`;
const telegramText = [
  publishStaging ? 'Staging workflow import completed and publish was requested. Review it in backoffice before approving production.' : 'Staging workflow import completed as an unpublished draft. Review it in backoffice before approving production.',
  `Workflow: ${fileName}`,
  `Repo: ${repo}`,
  `Branch: ${branch}`,
  `Source path: ${workflowPath}`,
  `Publish staging: ${publishStaging}`,
  `Approval id: ${approvalId}`
].join('\n');
return [{ json: { repo, branch, workflowPath, fileName, stagingInput, productionInput, downloadUrl, approvalUrl, approvalId, approvalRecordPath, telegramText, publishStaging, importCommand } }];

const fs = require('fs');
const item = $input.first().json;
const query = item.query || {};
let source;
let target;
let name;
let approvalId = query.id || '';
if (approvalId) {
  if (!/^[a-f0-9]{24}$/.test(approvalId)) {
    throw new Error('Invalid approval id');
  }
  const recordPath = `/files/approvals/deploy-${approvalId}.json`;
  if (!fs.existsSync(recordPath)) {
    throw new Error('Approval request was not found or has expired');
  }
  const record = JSON.parse(fs.readFileSync(recordPath, 'utf8'));
  if (new Date(record.expiresAt).getTime() < Date.now()) {
    throw new Error('Approval request has expired');
  }
  source = record.stagingInput;
  target = record.productionInput;
  name = record.fileName;
} else {
  if (!$env.DEPLOY_APPROVAL_TOKEN || query.token !== $env.DEPLOY_APPROVAL_TOKEN) {
    throw new Error('Invalid production approval token');
  }
  name = query.name || 'workflow.json';
  source = query.source;
  target = query.target;
}
if (!/^[A-Za-z0-9._-]+\.json$/.test(name) || name.includes('..')) {
  throw new Error(`Refusing unsafe workflow filename: ${name}`);
}
const expectedSource = `/files/git/staging/${name}`;
const expectedTarget = `/files/git/production/${name}`;
if (source !== expectedSource || target !== expectedTarget) {
  throw new Error('Refusing mismatched promotion paths');
}
const sh = (value) => `'${String(value).replace(/'/g, `'\\''`)}'`;
const displayName = name.replace(/\.json$/, '').replace(/[-_]/g, ' ');
const existingExport = '/files/git/production/.existing-workflows.json';
const productionRelative = `production/${name}`;
const hardenJson = `const fs=require('fs');const crypto=require('crypto');const p=process.argv[1];const n=process.argv[2];const e=process.argv[3];const j=JSON.parse(fs.readFileSync(p,'utf8'));const base=(j.name||n).replace(/ - Staging Candidate$/,'').replace(/ - Production Candidate$/,'');const productionName=base+' - Production Candidate';let existingId='';try{const exported=JSON.parse(fs.readFileSync(e,'utf8'));const workflows=Array.isArray(exported)?exported:(Array.isArray(exported.workflows)?exported.workflows:[]);const existing=workflows.find(w=>w&&w.name===productionName&&w.id&&w.isArchived!==true&&w.archived!==true);if(existing){existingId=String(existing.id);const byName=new Map((existing.nodes||[]).map(node=>[node.name,node]));for(const node of (j.nodes||[])){const previous=byName.get(node.name);if(previous&&previous.credentials)node.credentials=previous.credentials;}}}catch{}j.id=existingId||crypto.randomUUID().replace(/[^A-Za-z0-9]/g,'').slice(0,16);j.active=false;j.name=productionName;fs.writeFileSync(p,JSON.stringify(j,null,2));`;
const gitSyncCommand = [
  `PRODUCTION_REL=${sh(productionRelative)}`,
  `REPO_DIR=''`,
  `for candidate in "${DEPLOY_GIT_REPO_DIR:-}" '/files/git' '/git/n8n-workflows'; do if [ -n "$candidate" ] && git -C "$candidate" rev-parse --is-inside-work-tree >/dev/null 2>&1; then REPO_DIR="$candidate"; break; fi; done`,
  `if [ -n "$REPO_DIR" ]; then mkdir -p "$REPO_DIR/production" && cp ${sh(target)} "$REPO_DIR/$PRODUCTION_REL" && git -C "$REPO_DIR" add -- "$PRODUCTION_REL" && if git -C "$REPO_DIR" diff --cached --quiet -- "$PRODUCTION_REL"; then echo 'No production workflow changes to commit.'; else git -C "$REPO_DIR" commit -m ${sh(`Promote ${name} to production`)} && git -C "$REPO_DIR" push; fi; else echo 'Skipping git sync: no git repository found. Set DEPLOY_GIT_REPO_DIR to enable production back-push.'; fi`
].join(' && ');
const promoteCommand = [
  `test -f ${sh(source)}`,
  `mkdir -p ${sh('/files/git/production')}`,
  `cp ${sh(source)} ${sh(target)}`,
  `(n8n export:workflow --all --output=${sh(existingExport)} >/dev/null 2>&1 || true)`,
  `node -e ${sh(hardenJson)} ${sh(target)} ${sh(displayName)} ${sh(existingExport)}`,
  `n8n import:workflow --input=${sh(target)}`,
  gitSyncCommand
].join(' && ');
const telegramText = [
  'Production workflow import completed after approval.',
  `Workflow: ${name}`,
  `Imported file: ${target}`,
  approvalId ? `Approval id: ${approvalId}` : '',
  'Production JSON was committed and pushed when a writable Git checkout was found.'
].filter(Boolean).join('\n');
return [{ json: { source, target, name, approvalId, promoteCommand, telegramText, responseText: `Production import queued for ${name}. You can close this page.` } }];

const fs = require('fs');
const item = $input.first().json;
const query = item.query || {};
const id = query.id || '';
if (!/^[a-f0-9]{24}$/.test(id)) {
  throw new Error('Invalid approval id');
}
const recordPath = `/files/approvals/deploy-${id}.json`;
if (!fs.existsSync(recordPath)) {
  throw new Error('Approval request was not found or has expired');
}
const record = JSON.parse(fs.readFileSync(recordPath, 'utf8'));
if (new Date(record.expiresAt).getTime() < Date.now()) {
  throw new Error('Approval request has expired');
}
const baseUrl = ($env.PUBLIC_N8N_BASE_URL || '').replace(/\/$/, '');
const approveUrl = `${baseUrl}/webhook/workflow-promote-production?id=${encodeURIComponent(id)}`;
function esc(value) {
  return String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
}
const rows = [
  ['Approval id', record.id],
  ['Workflow', record.fileName],
  ['Repository', record.repo],
  ['Branch', record.branch],
  ['Source path', record.workflowPath],
  ['Staging file', record.stagingInput],
  ['Production file', record.productionInput],
  ['Created', record.createdAt],
  ['Expires', record.expiresAt]
].map(([k, v]) => `<tr><th>${esc(k)}</th><td>${esc(v)}</td></tr>`).join('');
const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Deployment Approval</title><style>body{font-family:system-ui,-apple-system,Segoe UI,sans-serif;margin:0;background:#101820;color:#edf2f7}main{max-width:860px;margin:0 auto;padding:28px}h1{font-size:24px}table{width:100%;border-collapse:collapse;background:#172331;border:1px solid #2a3a4d}th,td{text-align:left;padding:12px;border-bottom:1px solid #2a3a4d;vertical-align:top;word-break:break-word}th{width:180px;color:#a9b8c7}.actions{margin-top:22px;display:flex;gap:12px;flex-wrap:wrap}.button{display:inline-block;background:#31c48d;color:#07140f;text-decoration:none;font-weight:700;padding:12px 16px;border-radius:8px}.muted{color:#a9b8c7}.danger{color:#f8b4b4}</style></head><body><main><p class="muted">n8n deployment backoffice</p><h1>Review production promotion</h1><p class="danger">Approve only after you reviewed the staging workflow in n8n.</p><table>${rows}</table><div class="actions"><a class="button" href="${esc(approveUrl)}">Approve production import</a></div><p class="muted">Telegram receives only this short backoffice link. Sensitive approval details are loaded from the server-side approval record.</p></main></body></html>`;
return [{ json: { html } }];
